import numpy as np
def equation(t, x, v, params):
    p0,p1,p2,p3,p4,a,w,A,B,D = params[0],params[1],params[2],params[3],params[4],params[5],params[6],params[7],params[8],params[9]
    E = np.exp(-a*t)
    return p0 + p1*x + p2*x**2 + p3/v + p4*t/v + E*(A*np.cos(w*t)+B*np.sin(w*t))*(1 + D/v)
